#!/usr/bin/env node
// Records an explicit build-time Auto opt-out in the Electron main bundle, so
// it stays effective after installation without a launch environment variable.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export function releaseModule(version, disabled = false) {
  return [
    "// Generated by scripts/prepare-desktop-free-release.mjs at build time. Do not edit or commit.",
    `export const version = ${JSON.stringify(version)};`,
    `export const disabled = ${JSON.stringify(disabled)};`,
    "",
  ].join("\n");
}

export function writeDesktopFreeReleaseModule({ version, outPath, environment = process.env }) {
  const disabled = [environment.OPENWORK_DISABLE_FREE_INFERENCE, environment.OPENWORK_DISABLE_HOSTED_MODELS, environment.VITE_DISABLE_OPENWORK_MODELS]
    .some((value) => /^(?:1|true|yes|on)$/i.test(value?.trim() ?? ""));
  mkdirSync(dirname(outPath), { recursive: true });
  writeFileSync(outPath, releaseModule(version, disabled), "utf8");
  return { disabled };
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const desktopRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
  const outIndex = process.argv.indexOf("--outfile");
  const outPath = outIndex >= 0 ? resolve(process.argv[outIndex + 1]) : resolve(desktopRoot, "electron", "generated", "desktop-free-release.mjs");
  const version = JSON.parse(readFileSync(resolve(desktopRoot, "package.json"), "utf8")).version;
  const result = writeDesktopFreeReleaseModule({ version, outPath });
  console.log(`[desktop-free-release] Auto ${result.disabled ? "disabled" : "enabled"} for ${version}`);
}
